-- Into ForeverRecipes' own tables (a row of theirs always wins), so everything reads one set.
for _, pair in ipairs({ { "ClientRecipes", "Recipes" }, { "ClientMeta", "RecipeMeta" }, { "ClientNames", "RecipeNames" },
		{ "ClientItemNames", "ItemNames" }, { "ClientTrainers", "Trainers" } }) do
	local from, into = ns[pair[1]], ns[pair[2]]
	if type(into) == "table" then
		for id, row in pairs(from) do
			if into[id] == nil then into[id] = row end
		end
	end
	ns[pair[1]] = nil
end
